#include <stdio.h>
#include <string.h>

int main(void) {
    int thanhGhi[4] = {0, 0, 0, 0};
    char lenh[16];
    while (scanf("%15s", lenh) == 1) {
        if (strcmp(lenh, "SET") == 0) {
            int r, v;
            if (scanf("%d %d", &r, &v) != 2) return 1;
            thanhGhi[r] = v;
        } else if (strcmp(lenh, "ADD") == 0) {
            int r, s;
            if (scanf("%d %d", &r, &s) != 2) return 1;
            thanhGhi[r] += thanhGhi[s];
        } else if (strcmp(lenh, "PRINT") == 0) {
            int r;
            if (scanf("%d", &r) != 1) return 1;
            printf("%d\n", thanhGhi[r]);
        }
    }
    return 0;
}
